import{_ as a,H as n,f as s,i as t}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"Native下如何获取调用栈？","description":"","frontmatter":{},"headers":[{"level":2,"title":"书本中的unwind","slug":"书本中的unwind","link":"#书本中的unwind","children":[]},{"level":2,"title":"Android中的unwind","slug":"android中的unwind","link":"#android中的unwind","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"扩展阅读","slug":"扩展阅读","link":"#扩展阅读","children":[]}],"relativePath":"Android开发高手课/Native下如何获取调用栈？.md","filePath":"Android开发高手课/Native下如何获取调用栈？.md","lastUpdated":1779815315000}'),i={name:"Android开发高手课/Native下如何获取调用栈？.md"};function r(p,e,l,o,c,d){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="native下如何获取调用栈" tabindex="-1">Native下如何获取调用栈？ <a class="header-anchor" href="#native下如何获取调用栈" aria-label="Permalink to &quot;Native下如何获取调用栈？&quot;">​</a></h1><p>你好，我是simsun，曾在微信从事Android开发，也是开源爱好者、Rust语言“铁粉”。应绍文邀请，很高兴可以在“高手课”里和你分享一些编译方面的底层知识。</p><p>当我们在调试Native崩溃或者在做profiling的时候是十分依赖backtrace的，高质量的backtrace可以大大减少我们修复崩溃的时间。但你是否了解系统是如何生成backtrace的呢？今天我们就来探索一下backtrace背后的故事。</p><p>下面是一个常见的Native崩溃。通常崩溃本身并没有任何backtrace信息，可以直接获得的就是当前寄存器的值，但显然backtrace才是能够帮助我们修复Bug的关键。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pid: 4637, tid: 4637, name: crasher  &amp;gt;&amp;gt;&amp;gt; crasher &amp;lt;&amp;lt;&amp;lt;</span></span>
<span class="line"><span>signal 6 (SIGABRT), code -6 (SI_TKILL), fault addr --------</span></span>
<span class="line"><span>Abort message: &#39;some_file.c:123: some_function: assertion &quot;false&quot; failed&#39;</span></span>
<span class="line"><span>    r0  00000000  r1  0000121d  r2  00000006  r3  00000008</span></span>
<span class="line"><span>    r4  0000121d  r5  0000121d  r6  ffb44a1c  r7  0000010c</span></span>
<span class="line"><span>    r8  00000000  r9  00000000  r10 00000000  r11 00000000</span></span>
<span class="line"><span>    ip  ffb44c20  sp  ffb44a08  lr  eace2b0b  pc  eace2b16</span></span>
<span class="line"><span>backtrace:</span></span>
<span class="line"><span>    #00 pc 0001cb16  /system/lib/libc.so (abort+57)</span></span>
<span class="line"><span>    #01 pc 0001cd8f  /system/lib/libc.so (__assert2+22)</span></span>
<span class="line"><span>    #02 pc 00001531  /system/bin/crasher (do_action+764)</span></span>
<span class="line"><span>    #03 pc 00002301  /system/bin/crasher (main+68)</span></span>
<span class="line"><span>    #04 pc 0008a809  /system/lib/libc.so (__libc_init+48)</span></span>
<span class="line"><span>    #05 pc 00001097  /system/bin/crasher (_start_main+38)</span></span></code></pre></div><p>在阅读后面的内容之前，你可以先给自己2分钟时间，思考一下系统是如何生成backtrace的呢？我们通常把生成backtrace的过程叫作unwind，unwind看似和我们平时开发并没有什么关系，但其实很多功能都是依赖unwind的。举个例子，比如你要绘制火焰图或者是在崩溃发生时得到backtrace，都需要依赖unwind。</p><h2 id="书本中的unwind" tabindex="-1">书本中的unwind <a class="header-anchor" href="#书本中的unwind" aria-label="Permalink to &quot;书本中的unwind&quot;">​</a></h2><p><strong>1. 函数调用过程</strong></p><p>如果你在大学时期修过汇编原理这门课程，相信你会对下面的内容还有印象。下图就是一个非常标准的函数调用的过程。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Android%E5%BC%80%E5%8F%91%E9%AB%98%E6%89%8B%E8%AF%BE/images/80498/09cd560f823de783e22af03a5f837f2a.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Android%E5%BC%80%E5%8F%91%E9%AB%98%E6%89%8B%E8%AF%BE/images/80498/09cd560f823de783e22af03a5f837f2a.png" alt=""></a></p><ul><li><p>首先假设我们处于函数main()并准备调用函数foo()，调用方会按倒序压入参数。此时第一个参数会在调用栈栈顶。</p></li><li><p>调用invoke foo()伪指令，压入当前寄存器EIP的值到栈，然后载入函数foo()的地址到EIP。</p></li><li><p>此时，由于我们已经更改了EIP的值（为foo()的地址），相当于我们已经进入了函数foo()。在执行一个函数之前，编译器都会给每个函数写一段序言（prologue），这里会压入旧的EBP值，并赋予当前EBP和ESP新的值，从而形成新的一个函数栈。</p></li><li><p>下一步就行执行函数foo()本身的代码了。</p></li><li><p>结束执行函数foo() 并准备返回，这里编译器也会给每个函数插入一段尾声（epilogue）用于恢复调用方的ESP和EBP来重建之前函数的栈和恢复寄存器。</p></li><li><p>执行返回指令（ret），被调用函数的尾声（epilogue）已经恢复了EBP和ESP，然后我们可以从被恢复的栈中依次pop出EIP、所有的参数以及被暂存的寄存器的值。</p></li></ul><p>读到这里，相信如果没有学过汇编原理的同学肯定会有一些懵，我来解释一下上面提到的寄存器缩写的具体含义，上述命名均使用了x86的命名方式。讲这些是希望你对函数调用有一个初步的理解，其中有很多细节在不同体系结构、不同编译器上的行为都有所区别，所以请你放松心情，跟我一起继续向后看。</p><blockquote><p>EBP：基址指针寄存器，指向栈帧的底部。</p><p>在ARM体系结构中，R11（ARM code）或者R7（Thumb code）起到了类似的作用。在ARM64中，此寄存器为X29。</p><p>ESP：栈指针寄存器，指向栈帧的栈顶 ， 在ARM下寄存器为R13。</p><p>EIP：指令寄存器，存储的是CPU下次要执行的指令的地址，ARM下为PC，寄存器为R15。</p></blockquote><p><strong>2. 恢复调用帧</strong></p><p>如果我们把上述过程缩小，站在更高一层视角去看，所有的函数调用栈都会形成调用帧（stack frame），每一个帧中都保存了足够的信息可以恢复调用函数的栈帧。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Android%E5%BC%80%E5%8F%91%E9%AB%98%E6%89%8B%E8%AF%BE/images/80498/017b900048f1be70ec870ea0750d2145.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Android%E5%BC%80%E5%8F%91%E9%AB%98%E6%89%8B%E8%AF%BE/images/80498/017b900048f1be70ec870ea0750d2145.png" alt=""></a></p><p>我们这里忽略掉其他不相关的细节，重点关注一下EBP、ESP和EIP。你可以看到EBP和ESP分别指向执行函数栈的栈底和栈顶。每次函数调用都会保存EBP和EIP用于在返回时恢复函数栈帧。这里所有被保存的EBP就像一个链表指针，不断地指向调用函数的EBP。 这样我们就可以此为线索，十分优雅地恢复整个调用栈。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Android%E5%BC%80%E5%8F%91%E9%AB%98%E6%89%8B%E8%AF%BE/images/80498/7ab1f6e1774731ec96b9c68843a73df8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Android%E5%BC%80%E5%8F%91%E9%AB%98%E6%89%8B%E8%AF%BE/images/80498/7ab1f6e1774731ec96b9c68843a73df8.png" alt=""></a></p><p>这里我们可以用下面的伪代码来恢复调用栈：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void debugger::print_backtrace() {</span></span>
<span class="line"><span>    auto curr_func = get_func_from_pc(get_pc());</span></span>
<span class="line"><span>    output_frame(curr_func);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    auto frame_pointer = get_register_value(m_pid, reg::rbp);</span></span>
<span class="line"><span>    auto return_address = read_mem(frame_pointer+8);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    while (dwarf::at_name(curr_func) != &quot;main&quot;) {</span></span>
<span class="line"><span>        curr_func = get_func_from_pc(ret_addr);</span></span>
<span class="line"><span>        output_frame(curr_func);</span></span>
<span class="line"><span>        frame_pointer = read_mem(frame_pointer);</span></span>
<span class="line"><span>        return_address = read_mem(frame_pointer+8);</span></span>
<span class="line"><span>    }</span></span></code></pre></div><p>但是在ARM体系结构中，出于性能的考虑，天才的开发者为了节约R7/R11寄存器，使其可以作为通用寄存器来使用，因此无法保证保存足够的信息来形成上述调用栈的（即使你向编译器传入了“-fno-omit-frame-pointer”）。比如下面两种情况，ARM就会不遵循一般意义上的序言（prologue），感兴趣的同学可以具体查看 <a href="https://www.cl.cam.ac.uk/~fms27/teaching/2001-02/arm-project/02-sort/apcs.txt#1018" target="_blank" rel="noreferrer">APCS Doc</a>。</p><ul><li><p>函数为叶函数，即在函数体内再没有任何函数调用。</p></li><li><p>函数体非常小。</p></li></ul><h2 id="android中的unwind" tabindex="-1">Android中的unwind <a class="header-anchor" href="#android中的unwind" aria-label="Permalink to &quot;Android中的unwind&quot;">​</a></h2><p>我们知道大部分Android手机使用的都是ARM体系结构，那在Android中需要如何进行unwind呢？我们需要分两种情况分别讨论。</p><p><strong>1. Debug版本unwind</strong></p><p>如果是Debug版本，我们可以通过“.debug_frame”（有兴趣的同学可以了解一下 <a href="http://www.dwarfstd.org/doc/DWARF4.pdf" target="_blank" rel="noreferrer">DWARF</a>）来帮助我们进行unwind。这种方法十分高效也十分准确，但缺点是调试信息本身很大，甚至会比程序段（.TEXT段）更大，所以我们是无法在Release版本中包含这个信息的。</p><blockquote><p>DWARF 是一种标准调试信息格式。DWARF最早与ELF文件格式一起设计, 但DWARF本身是独立的一种对象文件格式。\b本身DAWRF和ELF的名字并没有任何意义（侏儒、精灵，是不是像魔兽世界的角色 😃），后续为了方便宣传，才命名为Debugging With Attributed Record Formats。引自 <a href="https://en.wikipedia.org/wiki/DWARF#cite_note-eager-1" target="_blank" rel="noreferrer">wiki</a></p></blockquote><p><strong>2. Release版本unwind</strong></p><p>对于Release版本，系统使用了一种类似“.debug_frame”的段落，是更加紧凑的方法，我们可以称之为unwind table，具体来说在x86和ARM64平台上是“.eh_frame”和“.eh_frame_hdr”，在ARM32平台上为“.ARM.extab”和“.ARM.exidx”。</p><p>由于ARM32的标准早于DWARF的方法，所有ARM使用了自己的实现，不过它们的原理十分接近，后续我们只讨论“.eh_frame”，如果你对ARM32的实现特别感兴趣，可以参考 <a href="https://sourceware.org/binutils/docs/as/ARM-Unwinding-Tutorial.html" target="_blank" rel="noreferrer">ARM-Unwinding-Tutorial</a>。</p><p>“.eh_frame section”也是遵循DWARF的格式的，但DWARF本身十分琐碎也十分复杂，这里我们就不深入进去了，只涉及一些比较浅显的内容，你只需要了解DAWRF使用了一个被称为DI（Debugging Information Entry）的数据结构，去表示每个变量、变量类型和函数等在debug程序时需要用到的内容。</p><p>“.eh_frame”使用了一种很聪明的方法构成了一个非常大的表，表中包含了每个程序段的地址对应的相应寄存器的值以及返回地址等相关信息，下面就是这张表的示例（你可以使用 <code>readelf --debug-dump=frames-interp</code> 去查看相应的信息，Release版中会精简一些信息，但所有帮助我们unwind的寄存器信息都会被保留）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Android%E5%BC%80%E5%8F%91%E9%AB%98%E6%89%8B%E8%AF%BE/images/80498/03aa1ebfe910222910dee2b23c7a5770.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Android%E5%BC%80%E5%8F%91%E9%AB%98%E6%89%8B%E8%AF%BE/images/80498/03aa1ebfe910222910dee2b23c7a5770.png" alt=""></a></p><p>“.eh_frame section”至少包含了一个CFI（Call Frame Information）。每个CFI都包含了两个条目：独立的CIE（Common Information Entry）和至少一个FDE（Frame Description Entry）。通常来讲CFI都对应一个对象文件，FDE则描述一个函数。</p><p>“ <a href="https://refspecs.linuxfoundation.org/LSB_1.3.0/gLSB/gLSB/ehframehdr.html" target="_blank" rel="noreferrer">.eh_frame_hdr</a> section”包含了一系列属性，除了一些基础的meta信息，还包含了一列有序信息（初始地址，指向“.eh_frame”中FDE的指针），这些信息按照function排序，从而可以使用二分查找加速搜索。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Android%E5%BC%80%E5%8F%91%E9%AB%98%E6%89%8B%E8%AF%BE/images/80498/ba663ea69e7a64a716e37c7f6710f4d1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Android%E5%BC%80%E5%8F%91%E9%AB%98%E6%89%8B%E8%AF%BE/images/80498/ba663ea69e7a64a716e37c7f6710f4d1.png" alt=""></a></p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>总的来说，unwind第一个栈帧是最难的，由于ARM无法保证会压基址指针寄存器（EBP）进栈，所以我们需要借助一些额外的信息（.eh_frame）来帮助我们得到相应的基址指针寄存器的值。即使如此，生产环境还是会有各种栈破坏，所以还是有许多工作需要做，比如不同的调试器（GDB、LLDB）或者breakpad都实现了一些搜索算法去寻找潜在的栈帧，这里我们就不展开讨论了，感兴趣的同学可以查阅相关代码。</p><h2 id="扩展阅读" tabindex="-1">扩展阅读 <a class="header-anchor" href="#扩展阅读" aria-label="Permalink to &quot;扩展阅读&quot;">​</a></h2><p>下面给你一些外部链接，你可以阅读GCC中实现unwind的关键函数，有兴趣的同学可以在调试器中实现自己的unwinder。</p><ul><li><p><a href="https://gcc.gnu.org/git/gitweb.cgi?p=gcc.git;a=blob;f=libgcc/unwind.inc;h=12f62bca7335f3738fb723f00b1175493ef46345;hb=HEAD#l275" target="_blank" rel="noreferrer">_Unwind_Backtrace</a></p></li><li><p><a href="https://gcc.gnu.org/git/gitweb.cgi?p=gcc.git;a=blob;f=libgcc/unwind-dw2.c;h=b262fd9f5b92e2d0ea4f0e65152927de0290fcbd;hb=HEAD#l1222" target="_blank" rel="noreferrer">uw_frame_state_for</a></p></li><li><p><a href="https://gcc.gnu.org/git/gitweb.cgi?p=gcc.git;a=blob;f=libgcc/unwind-dw2.c;h=b262fd9f5b92e2d0ea4f0e65152927de0290fcbd;hb=HEAD#l1494" target="_blank" rel="noreferrer">uw_update_context</a></p></li><li><p><a href="https://gcc.gnu.org/git/gitweb.cgi?p=gcc.git;a=blob;f=libgcc/unwind-dw2.c;h=b262fd9f5b92e2d0ea4f0e65152927de0290fcbd;hb=HEAD#l1376" target="_blank" rel="noreferrer">uw_update_context_1</a></p></li></ul>`,41)])])}const b=a(i,[["render",r]]);export{u as __pageData,b as default};
